  "content": "{\n  \"$schema\": \"http://json-schema.org/draft-07/schema#\",\n  \"$id\": \"outline.schema.json\",\n  \"title\": \"小说故事大纲\",\n  \"description\": \"节奏规划参考，确保故事有合理的起承转合\",\n  \"type\": \"object\",\n  \"required\": [\"act_one\", \"act_two\", \"act_three\"],\n  \"properties\": {\n    \"act_one\": {\n      \"type\": \"object\",\n      \"description\": \"第一幕：开篇（20-30%篇幅）- 建立世界观、引入主角和核心冲突\",\n      \"required\": [\"description\", \"key_chapters\", \"turning_point\"],\n      \"properties\": {\n        \"description\": {\n          \"type\": \"string\",\n          \"description\": \"该幕的核心任务描述\"\n        },\n        \"key_chapters\": {\n          \"type\": \"array\",\n          \"description\": \"该幕的关键章节数组\",\n          \"minItems\": 1,\n          \"items\": {\n            \"type\": \"object\",\n            \"required\": [\"chapter_number\", \"chapter_title\", \"core_event\"],\n            \"properties\": {\n              \"chapter_number\": {\n                \"type\": \"integer\",\n                \"minimum\": 1,\n                \"description\": \"章节编号\"\n              },\n              \"chapter_title\": {\n                \"type\": \"string\",\n                \"description\": \"章节标题\"\n              },\n              \"core_event\": {\n                \"type\": \"string\",\n                \"description\": \"本章核心事件（1-2句话）\"\n              },\n              \"emotional_tone\": {\n                \"type\": \"string\",\n                \"description\": \"本章情感基调\"\n              },\n              \"key_scenes\": {\n                \"type\": \"array\",\n                \"description\": \"本章关键场景列表\",\n                \"items\": {\n                  \"type\": \"string\"\n                }\n              }\n            }\n          }\n        },\n        \"turning_point\": {\n          \"type\": \"string\",\n          \"description\": \"本幕结尾的转折点\"\n        }\n      }\n    },\n    \"act_two\": {\n      \"type\": \"object\",\n      \"description\": \"第二幕：挣扎（40-50%篇