     \"type\": \"object\",\n            \"required\": [\"chapter_number\", \"chapter_title\", \"core_event\"],\n            \"properties\": {\n              \"chapter_number\": {\n                \"type\": \"integer\",\n                \"minimum\": 1,\n                \"description\": \"章节编号\"\n              },\n              \"chapter_title\": {\n                \"type\": \"string\",\n                \"description\": \"章节标题\"\n              },\n              \"core_event\": {\n                \"type\": \"string\",\n                \"description\": \"本章核心事件（1-2句话）\"\n              },\n              \"emotional_tone\": {\n                \"type\": \"string\",\n                \"description\": \"本章情感基调\"\n              },\n              \"key_scenes\": {\n                \"type\": \"array\",\n                \"description\": \"本章关键场景列表\",\n                \"items\": {\n                  \"type\": \"string\"\n                }\n              }\n            }\n          }\n        },\n        \"turning_point\": {\n          \"type\": \"string\",\n          \"description\": \"本幕结尾的转折点（可选）\"\n        }\n      }\n    }\n  }\n}\n",
